Wang_2024_evorpacept_qsp <- function() {
  description <- paste(
    "QSP. Quantitative systems pharmacology platform for immuno-oncology in",
    "advanced non-small cell lung cancer (NSCLC), extended with a",
    "pharmacokinetic and pharmacodynamic module for the anti-CD47 antibody",
    "evorpacept (ALX-148) in combination with the anti-PD-L1 antibody",
    "durvalumab. Four physiological compartments (central, peripheral, tumour,",
    "tumour-draining lymph node) plus an endothelial endosomal compartment for",
    "FcRn recycling, APC endosomal / surface compartments and three",
    "immunological-synapse compartments (T-cell:cancer-cell, T-cell:APC and",
    "macrophage:cancer-cell). The evorpacept module adds target-mediated drug",
    "disposition through CD47 on red blood cells with cross-arm (bivalent)",
    "binding, FcRn-mediated recycling, and CD47-SIRP-alpha plus PD-1/PD-L1",
    "control of macrophage phagocytosis. The surrounding platform covers naive",
    "and activated CD4+/CD8+ T cell trafficking and proliferation, logistic",
    "tumour growth, antigen release, uptake, endosomal processing and MHC-I",
    "presentation for a self-antigen and a neo-antigen, TCR kinetic",
    "proofreading, PD-1/PD-L1/PD-L2/CTLA-4/CD28/CD80/CD86 checkpoint binding,",
    "M1/M2 macrophage recruitment and polarisation, MDSC recruitment with",
    "arginase-I and nitric-oxide suppression, Th-to-Treg transdifferentiation,",
    "and TGF-beta / IFN-gamma / IL-2 / IL-10 / IL-12 / CCL2 dynamics. 153 ODE",
    "states, 6 algebraic species, 40 repeated-assignment rules and 276",
    "parameters, translated from the SimBiology export in Supplementary Tables",
    "S2-S6 and cross-checked against the authors' MATLAB source (Zenodo",
    "doi:10.5281/zenodo.11093921). Deterministic mechanism model: the authors",
    "generated virtual patients by sampling the parameter distributions in",
    "Supplementary Table S1 rather than by fitting IIV or residual error, so no",
    "etas and no error model are encoded.",
    sep = " "
  )
  reference <- paste(
    "Wang H, Arulraj T, Anbari S, Popel AS. Quantitative systems pharmacology",
    "modeling of macrophage-targeted therapy combined with PD-L1 inhibition in",
    "advanced NSCLC. Clin Transl Sci. 2024;17(6):e13811. doi:10.1111/cts.13811.",
    "Model source code: Zenodo doi:10.5281/zenodo.11093921 (QSPIO-TNBC v4.0).",
    sep = " "
  )
  vignette <- "Wang_2024_evorpacept_qsp"

  units <- list(
    time          = "day",
    dosing        = "nmol",
    concentration = "nmol/L"
  )

  covariateData <- list()

  population <- list(
    species       = "human (in silico virtual cohort)",
    n_subjects    = 629L,
    disease_state = "advanced / metastatic non-small cell lung cancer",
    dose_range    = paste(
      "Evorpacept (ALX-148) 1, 3, 10 and 30 mg/kg as a 1-h intravenous infusion,",
      "dosed weekly; durvalumab 10 mg/kg every 2 weeks. The combination",
      "scenario is 10 mg/kg evorpacept weekly with 10 mg/kg durvalumab.",
      sep = " "
    ),
    notes = paste(
      "Virtual cohort of 629 patients drawn from the authors' earlier anti-PD-L1",
      "NSCLC analysis, generated by randomly sampling the 30 parameter",
      "distributions in Supplementary Table S1 and selecting plausible patients",
      "on the model-predicted CD8/CD4, CD8/Treg and M1/M2 ratios against NSCLC",
      "immunogenomic data. The evorpacept PK parameters were fitted to the mean",
      "concentration and CD47 occupancy from the phase I trial of ALX-148;",
      "durvalumab PK was inherited from the authors' earlier work. Body weight",
      "is 80 kg in the dosing schedule; pre-treatment tumour diameter is 3.7 cm.",
      sep = " "
    )
