    x_syn_T_APC_CTLA4 <- q_syn_T_APC_CTLA4/m_syn_T_APC
    x_syn_T_APC_CD80 <- q_syn_T_APC_CD80/m_syn_T_APC
    x_syn_T_APC_CD80m <- q_syn_T_APC_CD80m/m_syn_T_APC
    x_syn_T_APC_CD86 <- q_syn_T_APC_CD86/m_syn_T_APC
    x_syn_T_APC_CTLA4_aCTLA4 <- q_syn_T_APC_CTLA4_aCTLA4/m_syn_T_APC
    x_syn_T_APC_CTLA4_aCTLA4_CTLA4 <- q_syn_T_APC_CTLA4_aCTLA4_CTLA4/m_syn_T_APC
    x_syn_M_C_CD47_aCD47 <- q_syn_M_C_CD47_aCD47/m_syn_M_C
    x_syn_M_C_CD47_aCD47_CD47 <- q_syn_M_C_CD47_aCD47_CD47/m_syn_M_C
    x_syn_M_C_CD47 <- q_syn_M_C_CD47/m_syn_M_C
    x_syn_M_C_SIRPa <- q_syn_M_C_SIRPa/m_syn_M_C
    x_syn_M_C_CD47_SIRPa <- q_syn_M_C_CD47_SIRPa/m_syn_M_C
    x_syn_M_C_PD1_PDL1 <- q_syn_M_C_PD1_PDL1/m_syn_M_C
    x_syn_M_C_PD1_PDL2 <- q_syn_M_C_PD1_PDL2/m_syn_M_C
    x_syn_M_C_PD1 <- q_syn_M_C_PD1/m_syn_M_C
    x_syn_M_C_PDL1 <- q_syn_M_C_PDL1/m_syn_M_C
    x_syn_M_C_PDL2 <- q_syn_M_C_PDL2/m_syn_M_C
    x_syn_M_C_PD1_aPD1 <- q_syn_M_C_PD1_aPD1/m_syn_M_C
    x_syn_M_C_PD1_aPD1_PD1 <- q_syn_M_C_PD1_aPD1_PD1/m_syn_M_C
    x_syn_M_C_PDL1_aPDL1 <- q_syn_M_C_PDL1_aPDL1/m_syn_M_C
    x_syn_M_C_PDL1_aPDL1_PDL1 <- q_syn_M_C_PDL1_aPDL1_PDL1/m_syn_M_C
    x_syn_M_C_PDL1_CD80 <- q_syn_M_C_PDL1_CD80/m_syn_M_C
    x_syn_M_C_CD80 <- q_syn_M_C_CD80/m_syn_M_C
    x_syn_M_C_CD80m <- q_syn_M_C_CD80m/m_syn_M_C
    x_V_endo_aCD47 <- q_V_endo_aCD47/m_V_endo
    x_V_endo_FcRn <- q_V_endo_FcRn/m_V_endo
    x_V_endo_FcRn_aCD47 <- q_V_endo_FcRn_aCD47/m_V_endo

    # ---- tumour volume: state-dependent repeated assignment (Table S5 rule 1) ----
    x_V_T_C_x <- q_V_T_C_x
    x_V_T_T1_exh <- q_V_T_T1_exh
    x_V_T_Th_exh <- q_V_T_Th_exh
    x_V_T_C1 <- q_V_T_C1
    x_V_T_T0 <- q_V_T_T0
    x_V_T_T1 <- q_V_T_T1
    x_V_T_APC <- q_V_T_APC
    x_V_T_mAPC <- q_V_T_mAPC
    x_V_T_Th <- q_V_T_Th
    x_V_T_MDSC <- q_V_T_MDSC
    x_V_T_Mac_M1 <- q_V_T_Mac_M1
    x_V_T_Mac_M2 <- q_V_T_Mac_M2
    C_total <- 0*a_cell+x_V_T_C1   # Table S5 (C_total)
    T_total <- 0*a_cell+x_V_T_T0+x_V_T_T1+x_V_T_Th   # Table S5 (T_total)
    M_total <- x_V_T_Mac_M1+x_V_T_Mac_M2   # Table S5 (M_total)
    vol_V_T <- ((x_V_T_C_x+C_total)*vol_cell+(x_V_T_T1_exh+x_V_T_Th_exh+T_total)*vol_Tcell)/Ve_T+M_total*vol_Mcell/Ve_T   # Table S5 rule 1
    x_V_T_IFNg <- q_V_T_IFNg/vol_V_T
    x_V_T_P0 <- q_V_T_P0/vol_V_T
    x_V_T_P1 <- q_V_T_P1/vol_V_T
    x_V_T_aPD1 <- q_V_T_aPD1/vol_V_T
    x_V_T_aPDL1 <- q_V_T_aPDL1/vol_V_T
    x_V_T_aCTLA4 <- q_V_T_aCTLA4/vol_V_T
    x_V_T_TGFb <- q_V_T_TGFb/vol_V_T
    x_V_T_NO <- q_V_T_NO/vol_V_T
    x_V_T_ArgI <- q_V_T_ArgI/vol_V_T
    x_V_T_CCL2 <- q_V_T_CCL2/vol_V_T
    x_V_T_IL12 <- q_V_T_IL12/vol_V_T
    x_V_T_IL10 <- q_V_T_IL10/vol_V_T
    x_V_T_aCD47 <- q_V_T_aCD47/vol_V_T

    # ---- algebraic / repeated-assignment rules (Table S5) ----
    T_total_LN <- 0*a_cell+x_V_LN_T0+x_V_LN_T1+x_V_LN_Th   # Table S5 (T_total_LN)
    k_C1_therapy <- 0/day   # Table S5 (k_C1_therapy)
    Tregs_ <- x_V_T_T0   # Table S5 (Tregs_)
    H_APC <- n_sites_APC*x_V_LN_mAPC/(n_sites_APC*x_V_LN_mAPC+x_V_LN_nT0*n_T0_clones+a_cell)   # Table S5 (H_APC)
    H_mAPC <- n_sites_APC*x_V_LN_mAPC/(n_sites_APC*x_V_LN_mAPC+x_V_LN_nT1*n_T1_clones+a_cell)   # Table S5 (H_mAPC)
    H_APCh <- n_sites_APC*x_V_LN_mAPC/(n_sites_APC*x_V_LN_mAPC+x_V_LN_nT0*n_T1_clones+a_cell)   # Table S5 (H_APCh)
    pTCR_p0_MHC_tot <- a_k_M1p0_TCR_off/(a_k_M1p0_TCR_off+a_phi_M1p0_TCR)*(a_k_M1p0_TCR_p/(a_k_M1p0_TCR_off+a_k_M1p0_TCR_p))^N_M1p0_TCR*(0.5*(x_A_s_M1p0/n_T0_clones+a_TCR_p0_tot+a_k_M1p0_TCR_off/k_M1p0_TCR_on-a_TCR_p0_tot*sqrt(((x_A_s_M1p0/n_T0_clones+a_TCR_p0_tot+a_k_M1p0_TCR_off/k_M1p0_TCR_on)/a_TCR_p0_tot)^2-4*x_A_s_M1p0/n_T0_clones/a_TCR_p0_tot)))   # Table S5 (pTCR_p0_MHC_tot)
    H_P0 <- pTCR_p0_MHC_tot/(pTCR_p0_MHC_tot+a_p0_50)   # Table S5 (H_P0)
    pTCR_p1_MHC_tot <- a_k_M1p1_TCR_off/(a_k_M1p1_TCR_off+a_phi_M1p1_TCR)*(a_k_M1p1_TCR_p/(a_k_M1p1_TCR_off+a_k_M1p1_TCR_p))^N_M1p1_TCR*(0.5*(x_A_s_M1p1/n_T1_clones+a_TCR_p1_tot+a_k_M1p1_TCR_off/k_M1p1_TCR_on-a_TCR_p1_tot*sqrt(((x_A_s_M1p1/n_T1_clones+a_TCR_p1_tot+a_k_M1p1_TCR_off/k_M1p1_TCR_on)/a_TCR_p1_tot)^2-4*x_A_s_M1p1/n_T1_clones/a_TCR_p1_tot)))   # Table S5 (pTCR_p1_MHC_tot)
    H_P1 <- pTCR_p1_MHC_tot/(pTCR_p1_MHC_tot+a_p1_50)   # Table S5 (H_P1)
    x_syn_T_C1_PDL1_total <- x_syn_T_C1_PDL1+x_syn_T_C1_PD1_PDL1+x_syn_T_C1_PDL1_aPDL1+2*x_syn_T_C1_PDL1_aPDL1_PDL1+x_syn_T_C1_PDL1_CD80+x_syn_T_C1_PDL1_CD80_CD28+x_syn_T_C1_PDL1_CD80_CTLA4   # Table S5 (syn_T_C1.PDL1_total)
    x_syn_T_C1_PDL2_total <- x_syn_T_C1_PD1_PDL2+x_syn_T_C1_PDL2   # Table S5 (syn_T_C1.PDL2_total)
    H_PD1_C1 <- ((x_syn_T_C1_PD1_PDL1+x_syn_T_C1_PD1_PDL2)/PD1_50)^n_PD1/(((x_syn_T_C1_PD1_PDL1+x_syn_T_C1_PD1_PDL2)/PD1_50)^n_PD1+1)   # Table S5 (H_PD1_C1)
    H_CD28_C1 <- ((x_syn_T_C1_CD28_CD80+x_syn_T_C1_CD28_CD86+2*x_syn_T_C1_CD28_CD80_CD28+x_syn_T_C1_PDL1_CD80_CD28)/CD28_CD8X_50)^n_CD28_CD8X/(((x_syn_T_C1_CD28_CD80+x_syn_T_C1_CD28_CD86+2*x_syn_T_C1_CD28_CD80_CD28+x_syn_T_C1_PDL1_CD80_CD28)/CD28_CD8X_50)^n_CD28_CD8X+1)   # Table S5 (H_CD28_C1)
    x_syn_T_APC_PDL1_total <- x_syn_T_APC_PDL1+x_syn_T_APC_PD1_PDL1+x_syn_T_APC_PDL1_aPDL1+2*x_syn_T_APC_PDL1_aPDL1_PDL1+x_syn_T_APC_PDL1_CD80+x_syn_T_APC_PDL1_CD80_CD28+x_syn_T_APC_PDL1_CD80_CTLA4   # Table S5 (syn_T_APC.PDL1_total)
    x_syn_T_APC_PDL2_total <- x_syn_T_APC_PD1_PDL2+x_syn_T_APC_PDL2   # Table S5 (syn_T_APC.PDL2_total)
    H_PD1_APC <- ((x_syn_T_APC_PD1_PDL1+x_syn_T_APC_PD1_PDL2)/PD1_50)^n_PD1/(((x_syn_T_APC_PD1_PDL1+x_syn_T_APC_PD1_PDL2)/PD1_50)^n_PD1+1)   # Table S5 (H_PD1_APC)
    H_CD28_APC <- ((x_syn_T_APC_CD28_CD80+x_syn_T_APC_CD28_CD86+2*x_syn_T_APC_CD28_CD80_CD28+x_syn_T_APC_PDL1_CD80_CD28)/CD28_CD8X_50)^n_CD28_CD8X/(((x_syn_T_APC_CD28_CD80+x_syn_T_APC_CD28_CD86+2*x_syn_T_APC_CD28_CD80_CD28+x_syn_T_APC_PDL1_CD80_CD28)/CD28_CD8X_50)^n_CD28_CD8X+1)   # Table S5 (H_CD28_APC)
    H_TGFb <- x_V_T_TGFb/(x_V_T_TGFb+a_TGFb_50)   # Table S5 (H_TGFb)
    H_TGFb_Teff <- x_V_T_TGFb/(x_V_T_TGFb+a_TGFb_50_Teff)   # Table S5 (H_TGFb_Teff)
    N_aTh <- a_N0+N_costim*H_CD28_APC+N_IL2_CD4*x_V_LN_IL2/(a_IL2_50+x_V_LN_IL2)   # Table S5 (N_aTh)
    H_NO <- x_V_T_NO/(a_NO_50_Teff+x_V_T_NO)   # Table S5 (H_NO)
    H_ArgI_Teff <- x_V_T_ArgI/(a_ArgI_50_Teff+x_V_T_ArgI)   # Table S5 (H_ArgI_Teff)
    H_ArgI_Treg <- x_V_T_ArgI/(a_ArgI_50_Treg+x_V_T_ArgI)   # Table S5 (H_ArgI_Treg)
    H_MDSC <- 1-(1-H_NO)*(1-H_ArgI_Teff)   # Table S5 (H_MDSC)
    x_syn_M_C_PDL1_total <- x_syn_M_C_PDL1+x_syn_M_C_PD1_PDL1+x_syn_M_C_PDL1_aPDL1+2*x_syn_M_C_PDL1_aPDL1_PDL1+x_syn_M_C_PDL1_CD80   # Table S5 (syn_M_C.PDL1_total)
    x_syn_M_C_PDL2_total <- x_syn_M_C_PD1_PDL2+x_syn_M_C_PDL2   # Table S5 (syn_M_C.PDL2_total)
    H_SIRPa <- (x_syn_M_C_CD47_SIRPa/SIRPa_50)^n_SIRPa/((x_syn_M_C_CD47_SIRPa/SIRPa_50)^n_SIRPa+1)   # Table S5 (H_SIRPa)
    H_PD1_M <- ((x_syn_M_C_PD1_PDL1+x_syn_M_C_PD1_PDL2)/PD1_50)^n_PD1/(((x_syn_M_C_PD1_PDL1+x_syn_M_C_PD1_PDL2)/PD1_50)^n_PD1+1)   # Table S5 (H_PD1_M)
    H_Mac_C <- 1-(1-H_SIRPa)*(1-H_PD1_M)   # Table S5 (H_Mac_C)
    H_IL10 <- x_V_T_IL10/(a_IL10_50+x_V_T_IL10)   # Table S5 (H_IL10)
    H_IL10_phago <- x_V_T_IL10/(a_IL10_50_phago+x_V_T_IL10)   # Table S5 (H_IL10_phago)
    H_IL12 <- x_V_T_IL12/(a_IL12_50+x_V_T_IL12)   # Table S5 (H_IL12)
    R_Tcell <- 0*a_cell/day+(a_k_C1_death+k_C1_therapy)*x_V_T_C1+k_C_T1*x_V_T_C1*x_V_T_T1/(K_T_C*x_V_T_C1+x_V_T_T1+a_cell)*x_V_T_T1/(x_V_T_T1+K_T_Treg*Tregs_+a_cell)*(1-H_TGFb_Teff)*(1-H_PD1_C1)*(1-H_MDSC)+k_M1_phago*x_V_T_C1*x_V_T_Mac_M1/(x_V_T_Mac_M1+K_Mac_C*x_V_T_C1+a_cell)*(1-H_Mac_C)*(1-H_IL10_phago)   # Table S5 (R_Tcell)
    N_aT <- a_N0+N_costim*H_CD28_APC+N_IL2_CD8*x_V_LN_IL2/(a_IL2_50+x_V_LN_IL2)   # Table S5 (N_aT)
    N_aT0 <- a_N0+N_costim*H_CD28_APC+N_IL2_CD4*x_V_LN_IL2/(a_IL2_50+x_V_LN_IL2)   # Table S5 (N_aT0)

    # ---- reaction rates (Supplementary Table S4) ----
    v1 <- k_cell_clear*x_V_T_C_x   # R1 Clearance of dead cancer cells from tumor
    v2 <- k_cell_clear*x_V_T_T1_exh   # R2 Clearance of exhausted CD8 T cells from tumor
    v3 <- k_cell_clear*x_V_T_Th_exh   # R3 Clearance of exhausted CD4 T cells from tumor
    v4 <- k_C1_growth*x_V_T_C1*(1-C_total/C_max)   # R4 Cancer cell growth
    v5 <- a_k_C1_death*x_V_T_C1   # R5 Cancer cell death
    v6 <- Q_nT0_thym/div_T0   # R6 Thymic output of naive T cell to blood
    v7 <- k_nT0_pro/div_T0*x_V_P_nT0/(K_nT0_pro/div_T0+x_V_P_nT0)   # R7 Naive T cell proliferation in the peripheral compartment
    v8 <- k_nT0_pro/div_T0*x_V_LN_nT0/(K_nT0_pro/div_T0+x_V_LN_nT0)   # R8 Naive T cell proliferation in the TDLN compartment
    v9 <- k_nT0_death*x_V_P_nT0   # R9 Naive T cell death in the peripheral compartment
    v10 <- k_nT0_death*x_V_C_nT0   # R10 Naive T cell death in the central compartment
    v11 <- k_nT0_death*x_V_LN_nT0   # R11 Naive T cell death in the TDLN compartment
    v12 <- q_nT0_P_in*x_V_C_nT0   # R12 Naive T cell entry into the peripheral compartment
    v13 <- q_nT0_P_out*x_V_P_nT0   # R13 Naive T cell exit from the peripheral compartment
    v14 <- q_nT0_LN_in*x_V_C_nT0   # R14 Naive T cell entry into the lymph node
    v15 <- q_nT0_LN_out*x_V_LN_nT0   # R15 Naive T cell exit from the lymph node
    v16 <- k_T0_act*H_APC*H_P0*x_V_LN_nT0   # R16 Naive T cell activation
    v17 <- k_T0_act*H_APC*H_P0*x_V_LN_nT0*n_T0_clones   # R17 Naive T cell activation
    v18 <- k_T0_pro/N_aT0*x_V_LN_aT0   # R18 aT0 cell proliferation
    v19 <- k_T0_pro/N_aT0*2^N_aT0*x_V_LN_aT0   # R19 aT0 cell proliferation
    v20 <- k_T0_death*x_V_C_T0   # R20 T cell death in the central compartment
    v21 <- k_T0_death*x_V_P_T0   # R21 T cell death in the peripheral compartment
    v22 <- k_T0_death*x_V_LN_T0   # R22 T cell death in the lymph node compartment
    v23 <- k_T0_death*x_V_T_T0   # R23 T cell death in the tumor compartment
    v24 <- k_cell_clear*x_V_T_T0*(a_Kc_rec/(C_total^2+a_Kc_rec))   # R24 T cell clearance upon antigen clearance
    v25 <- q_T0_P_in*x_V_C_T0   # R25 T cell transport into the peripheral compartment
    v26 <- q_T0_P_out*x_V_P_T0   # R26 T cell transport out of the peripheral compartment
    v27 <- q_T0_T_in*vol_V_T*x_V_C_T0*(C_total^2/(C_total^2+a_Kc_rec))   # R27 T cell transport into the tumor compartment
    v28 <- q_T0_LN_out*x_V_LN_T0   # R28 T cell transport out of the lymph node compartment
    v29 <- k_IL2_deg*x_V_LN_IL2*m_V_LN   # R29 IL2 degradation
    v30 <- k_IL2_cons*x_V_LN_T1*x_V_LN_IL2/(a_IL2_50+x_V_LN_IL2)   # R30 IL2 consumption by T cells
    v31 <- k_IL2_cons*x_V_LN_T0*x_V_LN_IL2/(a_IL2_50_Treg+x_V_LN_IL2)   # R31 IL2 consumption by Tregs
    v32 <- Q_nT1_thym/div_T1   # R32 Thymic output of naive T cell to blood
    v33 <- k_nT1_pro/div_T1*x_V_P_nT1/(K_nT1_pro/div_T1+x_V_P_nT1)   # R33 Naive T cell proliferation in the peripheral compartment
    v34 <- k_nT1_pro/div_T1*x_V_LN_nT1/(K_nT1_pro/div_T1+x_V_LN_nT1)   # R34 Naive T cell proliferation in the TDLN compartment
    v35 <- k_nT1_death*x_V_P_nT1   # R35 Naive T cell death in the peripheral compartment
    v36 <- k_nT1_death*x_V_C_nT1   # R36 Naive T cell death in the central compartment
    v37 <- k_nT1_death*x_V_LN_nT1   # R37 Naive T cell death in the TDLN compartment
    v38 <- q_nT1_P_in*x_V_C_nT1   # R38 Naive T cell entry into the peripheral compartment
    v39 <- q_nT1_P_out*x_V_P_nT1   # R39 Naive T cell exit from the peripheral compartment
    v40 <- q_nT1_LN_in*x_V_C_nT1   # R40 Naive T cell entry into the lymph node
    v41 <- q_nT1_LN_out*x_V_LN_nT1   # R41 Naive T cell exit from the lymph node
    v42 <- k_T1_act*H_mAPC*H_P1*x_V_LN_nT1   # R42 Naive T cell activation
    v43 <- k_T1_act*H_mAPC*H_P1*x_V_LN_nT1*n_T1_clones   # R43 Naive T cell activation
    v44 <- k_T1_pro/N_aT*x_V_LN_aT1   # R44 aT1 cell proliferation
    v45 <- k_T1_pro/N_aT*2^N_aT*x_V_LN_aT1   # R45 aT1 cell proliferation
    v46 <- k_T1_death*x_V_C_T1   # R46 T cell death in the central compartment
    v47 <- k_T1_death*x_V_P_T1   # R47 T cell death in the peripheral compartment
    v48 <- k_T1_death*x_V_LN_T1   # R48 T cell death in the lymph node compartment
    v49 <- k_T1_death*x_V_T_T1   # R49 T cell death in the tumor compartment
    v50 <- k_cell_clear*x_V_T_T1*(a_Kc_rec/(C_total^2+a_Kc_rec))   # R50 T cell clearance upon antigen clearance
    v51 <- k_Treg*x_V_T_T1*Tregs_/(x_V_T_T1+Tregs_+a_cell)*H_IL10   # R51 T cell death from Tregs
    v52 <- k_T1*x_V_T_T1*C_total/(C_total+x_V_T_T1+a_cell)*H_PD1_C1   # R52 T cell death from cancer
    v53 <- q_T1_P_in*x_V_C_T1   # R53 T cell transport into the peripheral compartment
    v54 <- q_T1_P_out*x_V_P_T1   # R54 T cell transport out of the peripheral compartment
    v55 <- q_T1_T_in*vol_V_T*x_V_C_T1*(C_total^2/(C_total^2+a_Kc_rec))   # R55 T cell transport into the tumor compartment
    v56 <- q_T1_LN_out*x_V_LN_T1   # R56 T cell transport out of the lymph node compartment
    v57 <- k_IL2_sec*x_V_LN_aT1   # R57 IL2 secretion from activated T cells
    v58 <- k_IFNg_Tsec*x_V_T_T1   # R58 IFNg secretion from CD8 T cells in tumor
    v59 <- k_C_T1*x_V_T_C1*x_V_T_T1/(K_T_C*x_V_T_C1+x_V_T_T1+a_cell)*x_V_T_T1/(x_V_T_T1+K_T_Treg*Tregs_+a_cell)*(1-H_TGFb_Teff)*(1-H_PD1_C1)*(1-H_MDSC)   # R59 Cancer cell killing by T cells
    v60 <- k_APC_death*(APC0_T*vol_V_T-x_V_T_APC)   # R60 APC recruitment/death in the tumour
    v61 <- k_APC_death*(APC0_LN*m_V_LN-x_V_LN_APC)   # R61 APC recruitment/death in LN
    v62 <- k_APC_mat*x_V_T_APC*H_IL12*(1-H_IL10)   # R62 APC maturation in the tumour
    v63 <- k_APC_mig*x_V_T_mAPC   # R63 APC migration to the lymph node
    v64 <- k_mAPC_death*x_V_T_mAPC   # R64 mAPC death in the tumour
    v65 <- k_mAPC_death*x_V_LN_mAPC   # R65 mAPC death in the lymph node
    v66 <- kout*x_A_e_M1*m_A_e-kin*x_A_s_M1*m_A_s   # R66 MHC translocation
